// The deployed worker (wrangler.jsonc `main`): venue images (`/media/…`) are answered here, before
// Next, so one costs a cache lookup or a single fetch; every other request is the OpenNext app.
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import app from "./.open-next/worker.js";
import { serveVenueImage } from "./src/lib/markets/venue-image-proxy";

export default {
  fetch(request, env, ctx) {
    return new URL(request.url).pathname.startsWith("/media/")
      ? serveVenueImage(request, ctx)
      : app.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;
